const folder = msg.payload.folder || env.get('INFEROID_NOTES_FOLDER') || '';
if (!folder) { node.error('Choose a notes folder before running this workflow', msg); return; }
msg.filename = folder + '/meeting-' + new Date().toISOString().replace(/[:.]/g, '-') + '.md';
msg.payload = '# Meeting\n\n' + (msg.payload.notes || msg.payload.transcript || '');
return msg;
